<?php use App\Helpers\View; ?>
<section class="list-toolbar"><form method="get"><input name="q" value="<?= View::e($search) ?>" placeholder="Search farmers"><button class="button secondary">Search</button></form><a class="button primary" href="/farmers/create">Add farmer</a></section>
<section class="card"><div class="table-wrap"><table><thead><tr><th>Farmer ID</th><th>Name</th><th>Contact</th><th>Address</th><th>Registered</th><th>Actions</th></tr></thead><tbody>
<?php foreach ($rows as $row): ?><tr><td><?= (int) $row['farmer_id'] ?></td><td><?= View::e($row['first_name'].' '.$row['last_name']) ?></td><td><?= View::e($row['contact_number']) ?></td><td><?= View::e($row['address']) ?></td><td><?= View::e($row['date_registered']) ?></td><td><a href="/farmers/edit/<?= (int)$row['farmer_id'] ?>">Edit</a><?php if (($user['role_name']??'')==='Administrator'): ?><form method="post" action="/farmers/delete/<?= (int)$row['farmer_id'] ?>" class="inline-delete" onsubmit="return confirm('Delete this farmer?')"><input type="hidden" name="csrf_token" value="<?= View::e($token) ?>"><button type="submit">Delete</button></form><?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php if (!$rows): ?><p class="empty-state">No farmers found.</p><?php endif; ?></section>
